Action: Inspect the local app data schemas for Gringotts and BatBucks to calculate the burn rate and available cash.  
<tool_call>
<function=bash>
<parameter=command>python3 - <<'PY'
import os, glob, sqlite3
paths=[]
for root in ['/data','/home/user','/tmp','/var/tmp']:
    for pat in ['**/*.sqlite','**/*.sqlite3','**/*.db']:
        paths += glob.glob(os.path.join(root,pat), recursive=True)
for p in sorted(set(paths)):
    if any(s in p.lower() for s in ['vault','gring','bat','buck']):
        print('DB',p)
        try:
            con=sqlite3.connect(p); cur=con.cursor()
            print(cur.execute("select name from sqlite_master where type='table'").fetchall())
            for (t,) in cur.execute("select name from sqlite_master where type='table'").fetchall():
                print('TABLE',t,cur.execute(f'pragma table_info("{t}")').fetchall())
                for r in cur.execute(f'select * from "{t}" limit 3').fetchall(): print(' ',r)
            con.close()
        except Exception as e: print('ERR',e)
PY</parameter>
